2	//
3	// Both wallet source-login paths — the claim flow (`claim::authenticate_source_pds`) and the
4	// outbound migration (`migration_orchestrator::authenticate_migration_source`) — open a full
5	// session against the account's *current* PDS with a password `createSession` and wrap it in a
6	// Bearer `OAuthClient` (ADR-0021). A spec-strict PDS (bsky.social) gates the
7	// operations that follow — PLC/identity ops for the claim, minting the source's
8	// `com.atproto.server.createAccount` service-auth token for the migration — behind a full session;
9	// the atproto OAuth ceiling for a third-party client is `transition:generic`, which those
10	// operations refuse.
11	//
12	// The body is identical apart from which frontend-facing error enum it feeds. This module owns
13	// that body once and returns a neutral `SourceLoginError`; each caller keeps its own public enum
14	// and maps `SourceLoginError` in via `From`. Two distinct enums are a deliberate design
15	// choice — the goal is to share the *behavior + tests*, not collapse the contracts.
16	
17	use crate::oauth_client::OAuthClient;
18	
19	/// Neutral result of a source-PDS password login, mapped into each caller's frontend-facing error
20	/// enum (`ClaimError` / `MigrationError`) via `From`. The variants mirror exactly the ones both
21	/// callers used to produce inline, so the mapping is total and lossless.
22	#[derive(Debug)]
23	pub(crate) enum SourceLoginError {
24	    /// The account has email two-factor enabled: `createSession` returned `AuthFactorTokenRequired`
25	    /// and the PDS emailed a one-time code. The UI prompts for the code and re-invokes with it.
26	    TwoFactorRequired,
27	    /// The source PDS rejected the password (`createSession` 401). `message` is a fixed,
28	    /// user-safe string — never the server's raw text — so the UI can say "wrong password".
29	    SourceAuthFailed { message: String },
30	    /// The session the PDS returned is for a different account than the one being claimed/migrated.
31	    AccountMismatch,
32	    /// Refused to send the password to a non-HTTPS, non-loopback source PDS (endpoint from the DID
33	    /// document).
34	    InsecureSourceUrl,
35	    /// The source PDS rate-limited the login (HTTP 429). `retry_after` carries `Retry-After`.
36	    RateLimited { retry_after: Option<String> },
37	    /// A non-2xx the wallet doesn't model specially. `message` is the server's own error text.
38	    ServerError { message: String },
39	    /// Transport failure, or the returned session couldn't be turned into a Bearer client.
40	    NetworkError { message: String },
41	}
42	
43	/// Shared core: run `createSession` against the source PDS and build a full-session Bearer
44	/// `OAuthClient`, enforcing the account-match guard. Extracted so both source-login paths share one
45	/// implementation and one behavioral test suite.
46	///
47	/// `expected_did` is the DID being claimed/migrated: the session the PDS returns MUST be for that
48	/// account, or the caller signed in to the wrong one and we refuse to bind those credentials rather
49	/// than act against the wrong identity. The password is used for one request and never stored.
50	pub(crate) async fn authenticate_source_password(
51	    pds_client: &crate::pds_client::PdsClient,
52	    pds_url: &str,
53	    expected_did: &str,
54	    identifier: &str,
55	    password: &str,
56	    auth_factor_token: Option<&str>,
57	) -> Result<OAuthClient, SourceLoginError> {
58	    let session = pds_client
59	        .create_session(pds_url, identifier, password, auth_factor_token)
60	        .await
61	        .map_err(|e| match e {
62	            crate::pds_client::PdsClientError::AuthFactorTokenRequired => {
63	                tracing::info!("source account has email 2FA; a code was sent");
64	                SourceLoginError::TwoFactorRequired
65	            }
66	            crate::pds_client::PdsClientError::InvalidCredentials { message } => {
67	                tracing::warn!(detail = %message, "source createSession rejected the password");
68	                SourceLoginError::SourceAuthFailed {
69	                    message: "The PDS did not accept that password.".to_string(),
70	                }
71	            }
72	            crate::pds_client::PdsClientError::InsecurePdsUrl { url } => {
73	                tracing::error!(pds_url = %url, "refusing password login to a non-HTTPS PDS");
74	                SourceLoginError::InsecureSourceUrl
75	            }
76	            // A rate limit or other server rejection during the password login must keep its real
77	            // reason too — a 429 here is not a connectivity problem.
78	            crate::pds_client::PdsClientError::RateLimited { retry_after, .. } => {
79	                SourceLoginError::RateLimited { retry_after }
80	            }
81	            crate::pds_client::PdsClientError::XrpcError { message, .. } => {
82	                SourceLoginError::ServerError { message }
83	            }
84	            other => SourceLoginError::NetworkError {
85	                message: format!("createSession failed: {}", other),
86	            },
87	        })?;
88	
89	    // The session must be for the account being claimed/migrated. A mismatch means the user signed
90	    // in to a different account (or a hostile PDS returned someone else's session) — refuse to bind
91	    // those credentials rather than act against the wrong identity.
92	    if session.did != expected_did {
93	        tracing::warn!(
94	            expected = %expected_did,
95	            got = %session.did,
96	            "source session DID does not match the expected identity"
97	        );
98	        return Err(SourceLoginError::AccountMismatch);
99	    }
100	
101	    OAuthClient::new_bearer(session.access_jwt, session.refresh_jwt, pds_url.to_string()).map_err(
102	        |e| {
103	            tracing::error!(error = %e, "failed to build Bearer client from source session");
104	            SourceLoginError::NetworkError {
105	                message: "failed to build source session client".to_string(),
106	            }
107	        },
108	    )
109	}
110	
111	#[cfg(test)]
112	mod tests {
113	    use super::*;
114	
115	    /// Build a Bearer-session JWT with a future `exp` so `new_bearer` derives a live expiry.
116	    fn future_exp_jwt() -> String {
117	        use base64::engine::general_purpose::URL_SAFE_NO_PAD;
118	        use base64::Engine;
119	        let now = std::time::SystemTime::now()
120	            .duration_since(std::time::UNIX_EPOCH)
121	            .unwrap()
122	            .as_secs();
123	        let header = URL_SAFE_NO_PAD.encode(r#"{"alg":"ES256"}"#);
124	        let payload = URL_SAFE_NO_PAD.encode(format!(r#"{{"exp":{}}}"#, now + 3600).as_bytes());
125	        format!("{}.{}.sig", header, payload)
126	    }
127	
128	    /// Happy path: a 200 `createSession` yields a full-session Bearer client bound to the PDS URL.
129	    #[tokio::test]
130	    async fn test_authenticate_source_password_success() {
131	        crate::keychain::clear_for_test();
132	        use httpmock::MockServer;
133	
134	        let server = MockServer::start();
135	        let access_jwt = future_exp_jwt();
136	        let access_for_body = access_jwt.clone();
137	        server.mock(move |when, then| {
138	            when.method(httpmock::Method::POST)
139	                .path("/xrpc/com.atproto.server.createSession");
140	            then.status(200).json_body(serde_json::json!({
141	                "accessJwt": access_for_body,
142	                "refreshJwt": "refresh_jwt",
143	                "did": "did:plc:test",
144	                "handle": "alice.example.com",
145	            }));
146	        });
147	
148	        let pds_client = crate::pds_client::PdsClient::new();
149	        let result = authenticate_source_password(
150	            &pds_client,
151	            &server.base_url(),
152	            "did:plc:test",
153	            "alice.example.com",
154	            "hunter2",
155	            None,
156	        )
157	        .await;
158	        assert!(
159	            result.is_ok(),
160	            "createSession 200 must build a Bearer client"
161	        );
162	    }
163	
164	    /// A 200 whose `did` differs from the expected DID must be refused (wrong-account guard).
165	    #[tokio::test]
166	    async fn test_authenticate_source_password_did_mismatch() {
167	        crate::keychain::clear_for_test();
168	        use httpmock::MockServer;
169	
170	        let server = MockServer::start();
171	        let access_jwt = future_exp_jwt();
172	        let access_for_body = access_jwt.clone();
173	        server.mock(move |when, then| {
174	            when.method(httpmock::Method::POST)
175	                .path("/xrpc/com.atproto.server.createSession");
176	            then.status(200).json_body(serde_json::json!({
177	                "accessJwt": access_for_body,
178	                "refreshJwt": "refresh_jwt",
179	                "did": "did:plc:someone-else",
180	                "handle": "mallory.example.com",
181	            }));
182	        });
183	
184	        let pds_client = crate::pds_client::PdsClient::new();
185	        let result = authenticate_source_password(
186	            &pds_client,
187	            &server.base_url(),
188	            "did:plc:test",
189	            "alice.example.com",
190	            "hunter2",
191	            None,
192	        )
193	        .await;
194	        assert!(
195	            matches!(result, Err(SourceLoginError::AccountMismatch)),
196	            "a session for a different DID must be refused, got: {:?}",
197	            result.err()
198	        );
199	    }
200	
201	    /// The password must never be sent to a non-HTTPS, non-loopback PDS — refused before any
202	    /// network call, so no mock server is needed.
203	    #[tokio::test]
204	    async fn test_authenticate_source_password_rejects_insecure_url() {
205	        crate::keychain::clear_for_test();
206	        let pds_client = crate::pds_client::PdsClient::new();
207	        let result = authenticate_source_password(
208	            &pds_client,
209	            "http://pds.example.com",
210	            "did:plc:test",
211	            "alice.example.com",
212	            "hunter2",
213	            None,
214	        )
215	        .await;
216	        assert!(
217	            matches!(result, Err(SourceLoginError::InsecureSourceUrl)),
218	            "a non-HTTPS PDS URL must be refused, got: {:?}",
219	            result.err()
220	        );
221	    }
222	
223	    /// A 401 `createSession` (wrong password) surfaces as SourceAuthFailed, never NetworkError.
224	    #[tokio::test]
225	    async fn test_authenticate_source_password_wrong_password() {
226	        crate::keychain::clear_for_test();
227	        use httpmock::MockServer;
228	
229	        let server = MockServer::start();
230	        server.mock(|when, then| {
231	            when.method(httpmock::Method::POST)
232	                .path("/xrpc/com.atproto.server.createSession");
233	            then.status(401).json_body(serde_json::json!({
234	                "error": "AuthenticationRequired",
235	                "message": "Invalid identifier or password"
236	            }));
237	        });
238	
239	        let pds_client = crate::pds_client::PdsClient::new();
240	        let result = authenticate_source_password(
241	            &pds_client,
242	            &server.base_url(),
243	            "did:plc:test",
244	            "alice.example.com",
245	            "wrong",
246	            None,
247	        )
248	        .await;
249	        assert!(
250	            matches!(result, Err(SourceLoginError::SourceAuthFailed { .. })),
251	            "a 401 must surface as SourceAuthFailed, got: {:?}",
252	            result.err()
253	        );
254	    }
255	
256	    /// An email-2FA account answers a token-less attempt with `AuthFactorTokenRequired`, which must
257	    /// surface as `TwoFactorRequired` (prompt for a code), NOT `SourceAuthFailed` (wrong password).
258	    #[tokio::test]
259	    async fn test_authenticate_source_password_two_factor_required() {
260	        crate::keychain::clear_for_test();
261	        use httpmock::MockServer;
262	
263	        let server = MockServer::start();
264	        server.mock(|when, then| {
265	            when.method(httpmock::Method::POST)
266	                .path("/xrpc/com.atproto.server.createSession");
267	            then.status(401).json_body(serde_json::json!({
268	                "error": "AuthFactorTokenRequired",
269	                "message": "A sign in code has been sent to your email address"
270	            }));
271	        });
272	
273	        let pds_client = crate::pds_client::PdsClient::new();
274	        let result = authenticate_source_password(
275	            &pds_client,
276	            &server.base_url(),
277	            "did:plc:test",
278	            "alice.example.com",
279	            "correct-password",
280	            None,
281	        )
282	        .await;
283	        assert!(
284	            matches!(result, Err(SourceLoginError::TwoFactorRequired)),
285	            "AuthFactorTokenRequired must surface as TwoFactorRequired, got: {:?}",
286	            result.err()
287	        );
288	    }
